import{_ as e,I as o,g as a,j as r}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","frontmatter":{"title":"Глобальные настройки","description":"Смена языка, валюты учета и инструменты аварийного сброса данных в ОмниКрафт ЕРП.","order":16},"headers":[],"relativePath":"ru/docs/global-settings.md","filePath":"ru/docs/global-settings.md"}'),l={name:"ru/docs/global-settings.md"};function n(d,t,s,i,c,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="⚙️-глобальные-настроики-язык-валюта-и-безопасность" tabindex="-1">⚙️ Глобальные настройки: Язык, Валюта и Безопасность <a class="header-anchor" href="#⚙️-глобальные-настроики-язык-валюта-и-безопасность" aria-label="Permalink to &quot;⚙️ Глобальные настройки: Язык, Валюта и Безопасность&quot;">​</a></h1><p>В отличие от <em>Настроек пространства</em>, которые влияют на экономику конкретного бизнеса (ставки, наценки, накладные расходы), <strong>Глобальные настройки</strong> задают фундаментальные правила работы всего приложения и вашей локальной базы данных.</p><p>Чтобы открыть их, нажмите в верхнем меню <strong>Файл ➔ Настройки программы</strong>.</p><hr><h2 id="🌍-локализация-и-валюта" tabindex="-1">🌍 Локализация и Валюта <a class="header-anchor" href="#🌍-локализация-и-валюта" aria-label="Permalink to &quot;🌍 Локализация и Валюта&quot;">​</a></h2><h3 id="_1-язык-интерфеиса" tabindex="-1">1. Язык интерфейса <a class="header-anchor" href="#_1-язык-интерфеиса" aria-label="Permalink to &quot;1. Язык интерфейса&quot;">​</a></h3><p>Программа поддерживает полную локализацию интерфейса. При самом первом запуске ОмниКрафт ЕРП автоматически сканирует язык вашей операционной системы и подстраивается под него. Вы можете в любой момент переключиться между <strong>Русским (RU)</strong> и <strong>English (EN)</strong>.</p><ul><li><strong>Как работает:</strong> Изменение языка требует полного перезапуска приложения, чтобы все системные окна, категории ДДС и справочники корректно перевелись и подгрузились из словарей.</li></ul><h3 id="_2-валюта-учета" tabindex="-1">2. Валюта учета <a class="header-anchor" href="#_2-валюта-учета" aria-label="Permalink to &quot;2. Валюта учета&quot;">​</a></h3><p>По умолчанию программа подтягивает символ национальной валюты из региональных настроек вашей ОС (например, <code>₽</code>, <code>$</code>, <code>€</code>, <code>₸</code>, <code>₺</code>). Вы можете изменить её на любую другую через удобный встроенный поиск (просто начните вводить название, например, <em>«лира»</em> или <em>«юань»</em>).</p><div class="warning custom-block"><p class="custom-block-title">Защита исторических данных</p><p>Кнопка смены валюты <strong>автоматически блокируется</strong>, как только вы начинаете вести реальный учет (создаете первую закупку, продажу или запись в ДДС). Это сделано для защиты вашей финансовой отчетности. Если бы программа позволяла на лету менять валюту с рублей на доллары, все ваши прошлые чеки, балансы и графики аналитики мгновенно превратились бы в математическую кашу. <strong>Что делать, если вы переехали в другую страну?</strong> Вам потребуется выполнить «Сброс учета» (см. ниже), чтобы начать вести книги в новой валюте с чистого листа, сохранив при этом справочники и рецепты.</p></div><hr><h2 id="🤖-интеллектуальные-функции-ии" tabindex="-1">🤖 Интеллектуальные функции (ИИ) <a class="header-anchor" href="#🤖-интеллектуальные-функции-ии" aria-label="Permalink to &quot;🤖 Интеллектуальные функции (ИИ)&quot;">​</a></h2><p>ОмниКрафт ЕРП предоставляет интеллектуальные функции помощи мастеру на базе искусственного интеллекта по принципу использования собственного ключа API (прямой доступ к нейросетям без серверов-посредников).</p><p>Все запросы к нейросетям отправляются <strong>напрямую с вашего компьютера</strong> на серверы выбранного поставщика. Ваши коммерческие данные, рецепты, клиентские базы и финансовые отчеты никогда не передаются на промежуточные серверы разработчиков ОмниКрафт ЕРП, что обеспечивает 100% приватность и конфиденциальность.</p><h3 id="_1-поддерживаемые-поставщики-неиросетеи" tabindex="-1">1. Поддерживаемые поставщики нейросетей <a class="header-anchor" href="#_1-поддерживаемые-поставщики-неиросетеи" aria-label="Permalink to &quot;1. Поддерживаемые поставщики нейросетей&quot;">​</a></h3><ul><li><strong>OpenAI</strong> (<code>gpt-4o</code>, <code>gpt-4o-mini</code>, <code>o1</code>, <code>o3-mini</code>);</li><li><strong>DeepSeek</strong> (<code>deepseek-chat</code>, <code>deepseek-reasoner</code>);</li><li><strong>Google Gemini</strong> (<code>gemini-1.5-flash</code>, <code>gemini-1.5-pro</code>, <code>gemini-2.0</code>);</li><li><strong>OpenRouter</strong> (доступ к каталогу моделей через единый ключ API);</li><li><strong>Собственный сервер / локальная служба</strong> (<code>Ollama</code>, <code>vLLM</code> и локальные модели).</li></ul><h3 id="_2-аппаратная-защита-ключеи-windows-dpapi" tabindex="-1">2. Аппаратная защита ключей (<code>Windows DPAPI</code>) <a class="header-anchor" href="#_2-аппаратная-защита-ключеи-windows-dpapi" aria-label="Permalink to &quot;2. Аппаратная защита ключей (`Windows DPAPI`)&quot;">​</a></h3><p>Ваш ключ API сохраняется в зашифрованном виде с использованием технологии аппаратной криптографической защиты операционной системы (<code>Windows DPAPI</code>). Ключ привязан к учетной записи и аппаратному обеспечению вашего компьютера, что исключает его компрометацию сторонними программами или при случайном копировании файлов настроек.</p><h3 id="_3-кнопки-помощники-«кнопки-искры»-✨-в-формах" tabindex="-1">3. Кнопки-помощники («кнопки-искры» ✨) в формах <a class="header-anchor" href="#_3-кнопки-помощники-«кнопки-искры»-✨-в-формах" aria-label="Permalink to &quot;3. Кнопки-помощники («кнопки-искры» ✨) в формах&quot;">​</a></h3><p>При включенном ИИ в ключевых рабочих пространствах программы становятся доступны кнопки экспресс-анализа:</p><ul><li><strong>Калькулятор тиража:</strong> экономический аудит себестоимости партии, выявление главного драйвера издержек и советы по оптимизации цены.</li><li><strong>Склад сырья:</strong> генерация профессионального описания номенклатуры, характеристик материала и правил складского хранения в один клик.</li><li><strong>Верстак производства:</strong> формирование технологической памятки мастера с контрольными точками качества и оценкой сырьевых рисков.</li></ul><p>Если ключ API еще не настроен, нажатие на кнопку-помощник отобразит деликатную подсказку с возможностью перейти к настройкам в один клик. Программа всегда остается на 100% работоспособной даже без подключения ИИ.</p><h3 id="_4-внутреннии-ии-помощник-выдвижная-правая-панель" tabindex="-1">4. Внутренний ИИ-помощник (Выдвижная правая панель) <a class="header-anchor" href="#_4-внутреннии-ии-помощник-выдвижная-правая-панель" aria-label="Permalink to &quot;4. Внутренний ИИ-помощник (Выдвижная правая панель)&quot;">​</a></h3><p>С правой стороны главного окна программы расположена компактная выдвижная панель персонального ИИ-помощника.</p><ul><li><strong>Ненавязчивость по умолчанию:</strong> Панель свернута в тонкую полосу (38 пикселей) с аккуратным значком и не отвлекает мастера от повседневной работы.</li><li><strong>Контекст экрана («карта + детали по запросу»):</strong> Помощник видит активную вкладку программы (Склад, Верстак, Калькулятор, Продажи) и отвечает на вопросы с учетом текущих остатков и параметров. Вы можете в любой момент отключить передачу контекста экрана с помощью переключателя в шапке панели или нажать значок глаза, чтобы увидеть точный снимок отправляемых данных.</li><li><strong>Безопасность операций (Человек в контуре управления):</strong> Если ИИ предлагает выполнить операцию (например, создать персональную ссылку или обновить статус), он выводит карточку действия. Любые изменения данных выполняются <strong>только после вашего прямого подтверждения</strong> кнопкой «Выполнить».</li><li><strong>Приватный режим:</strong> При выборе локальной модели (например, Ollama) отображается зеленый знак «Офлайн», гарантирующий, что ваши запросы обрабатываются исключительно на вашем компьютере.</li></ul><h3 id="_5-внешние-ии-агенты-служба-mcp" tabindex="-1">5. Внешние ИИ-агенты (служба <code>MCP</code>) <a class="header-anchor" href="#_5-внешние-ии-агенты-служба-mcp" aria-label="Permalink to &quot;5. Внешние ИИ-агенты (служба `MCP`)&quot;">​</a></h3><p>ОмниКрафт ЕРП поддерживает стандартизированный протокол взаимодействия с внешними автономными агентами (протокол контекста модели — <code>Model Context Protocol</code>, <code>MCP</code>, спецификация 2024-11-05). Это позволяет подключать внешние среды разработки и агентские клиенты (<code>Cursor</code>, <code>Claude Desktop</code>, <code>Antigravity</code>) напрямую к программе через локальный межпроцессный канал (<code>stdio</code>).</p><ul><li><strong>Единая точка входа:</strong> Все зарегистрированные модули программы автоматически предоставляют свои инструменты через единый реестр. Внешний агент подключается одним конфигурационным файлом и видит доступные возможности всей системы.</li><li><strong>Токен сопряжения и отзыв в один клик:</strong> Для безопасной авторизации внешнего агента в Настройках программы генерируется уникальный криптографический токен сопряжения. Если вы хотите закрыть доступ агенту, достаточно нажать кнопку «Отозвать токен» — сопряжение мгновенно аннулируется.</li><li><strong>Готовая конфигурация:</strong> По нажатию кнопки «Скопировать <code>JSON</code>-конфиг» программа формирует готовый блок настроек для вставки в конфигурационный файл вашего агента (<code>claude_desktop_config.json</code> или <code>cursor/mcp.json</code>).</li><li><strong>Доверенный режим (Защита от несанкционированных изменений):</strong> По умолчанию внешнему агенту разрешены только безопасные операции чтения (<code>read-only</code>). Любые изменяющие операции (<code>mutating</code>), такие как создание ссылок или изменение статусов, блокируются на уровне ядра. Для их разрешения необходимо осознанно активировать переключатель «Доверенный режим» в Настройках программы.</li><li><strong>Сквозной журнал аудита:</strong> Каждое действие внешнего агента фиксируется в системном журнале с фиксацией имени агента, параметров вызова, статуса и времени отклика в миллисекундах.</li></ul><hr><h2 id="☢️-опасная-зона-danger-zone" tabindex="-1">☢️ Опасная зона (Danger Zone) <a class="header-anchor" href="#☢️-опасная-зона-danger-zone" aria-label="Permalink to &quot;☢️ Опасная зона (Danger Zone)&quot;">​</a></h2><p>В нижней части окна настроек расположены инструменты для радикального вмешательства в базу данных. Эти кнопки следует использовать только осознанно.</p><h3 id="🧹-сброс-учета-очистка-истории" tabindex="-1">🧹 Сброс учета (Очистка истории) <a class="header-anchor" href="#🧹-сброс-учета-очистка-истории" aria-label="Permalink to &quot;🧹 Сброс учета (Очистка истории)&quot;">​</a></h3><p>Этот инструмент предназначен для <strong>«обнуления» операционной памяти</strong> бизнеса без потери его инфраструктуры. Он идеально подходит, если вы использовали программу в тестовом режиме, набили много черновых чеков, и теперь хотите начать вести реальные дела с чистого листа.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Что будет УДАЛЕНО (Журналы)</th><th style="text-align:left;">Что будет ОБНУЛЕНО (Остатки)</th><th style="text-align:left;">Что будет СОХРАНЕНО (Инфраструктура)</th></tr></thead><tbody><tr><td style="text-align:left;">• Вся история продаж (чеки)</td><td style="text-align:left;">• Физические остатки сырья на складе</td><td style="text-align:left;">• Всё оборудование и активы (Мастерская)</td></tr><tr><td style="text-align:left;">• Журнал складских движений</td><td style="text-align:left;">• Остатки готовой продукции (Витрина)</td><td style="text-align:left;">• Справочники сырья и ссылки на поставщиков</td></tr><tr><td style="text-align:left;">• Реестр денежных операций (ДДС)</td><td style="text-align:left;">• Сальдо кассы и история ДДС</td><td style="text-align:left;">• Все шаблоны изделий и Рецепты</td></tr><tr><td style="text-align:left;">• Очередь производства (Верстак)</td><td style="text-align:left;">• Себестоимость партий ФИФО</td><td style="text-align:left;">• Категории, упаковки, глобальные настройки</td></tr></tbody></table><p>Перед выполнением очистки программа автоматически сделает теневой бэкап базы данных. После нажатия кнопки <strong>«Очистить историю»</strong> ОмниКрафт ЕРП предложит автоматическую перезагрузку. Вы получите чистую мастерскую, готовую к инвентаризации стартовых остатков (см. <a href="./getting-started">Быстрый старт</a>).</p><h3 id="💥-полныи-сброс-factory-reset" tabindex="-1">💥 Полный сброс (Factory Reset) <a class="header-anchor" href="#💥-полныи-сброс-factory-reset" aria-label="Permalink to &quot;💥 Полный сброс (Factory Reset)&quot;">​</a></h3><p>Это кнопка «Красная таблетка». Она <strong>безвозвратно удаляет абсолютно всё</strong> из локальной базы данных SQLite.</p><ul><li>Все таблицы, справочники, рецепты, чеки, остатки, настройки и лицензионные ключи превращаются в пустоту.</li><li>При следующем запуске программа создаст базу заново, как будто вы только что скачали и установили ОмниКрафт ЕРП в самый первый раз.</li></ul><div class="danger custom-block"><p class="custom-block-title">Внимание!</p><p>Перед использованием этой функции <strong>обязательно</strong> сделайте ручной экспорт данных (<code>Файл ➔ Экспорт данных ➔ Резервная копия базы .db</code>), если есть хоть малейший шанс, что эта информация вам когда-либо понадобится. Восстановить данные после полного сброса без файла бэкапа невозможно.</p></div><hr><h2 id="🔄-автоматическая-перезагрузка" tabindex="-1">🔄 Автоматическая перезагрузка <a class="header-anchor" href="#🔄-автоматическая-перезагрузка" aria-label="Permalink to &quot;🔄 Автоматическая перезагрузка&quot;">​</a></h2><p>Любое изменение в Глобальных настройках (смена языка, валюты или сброс учета) требует пересборки конфигурации в оперативной памяти. После сохранения изменений программа предложит вам <strong>перезагрузиться сейчас</strong> или сделать это позже.</p><p>Во время перезагрузки ОмниКрафт ЕРП заботливо сохраняет геометрию вашего окна (размер и положение на экране), чтобы вы продолжили работу ровно там, где остановились.</p>',44)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
